import { readFileSync, writeFileSync } from 'node:fs';
export function readTokens() {
  const source = readFileSync(new URL('../../src/visitor-verdict.js', import.meta.url), 'utf8');
  const block = source.match(/agentTokens:\s*\[([\s\S]*?)\]/)?.[1];
  if (!block || !/^\s*(?:'[^'\\]*'\s*,?\s*)+$/.test(block))
    throw new Error('Token source format changed');
  return [...block.matchAll(/'([^']+)'/g)].map((m) => m[1]);
}
export function generated() {
  return (
    '// Generated by scripts/generate-tokens.mjs. Do not edit.\nexport const agentTokens: readonly string[] = ' +
    JSON.stringify(readTokens(), null, 2) +
    ';\n'
  );
}
if (process.argv[1] === new URL(import.meta.url).pathname)
  writeFileSync(new URL('../src/tokens.generated.ts', import.meta.url), generated());
